insert into public.products (id,category,name,tamil_name,description,badge,hue,image_url,variants,available,featured,favourite,sort)
select x->>'id',x->>'c',x->>'name',x->>'ta',x->>'frag',x->>'badge',(x->>'h')::int,x->>'img',x->'v',true,false,false,(t.ord-1)::int
from c, jsonb_array_elements(c.p->'products') with ordinality as t(x,ord)
on conflict (id) do nothing;
